-- Migration: Create Prompts Table
-- Purpose: Database schema for storing AI agent prompts with version control
-- Version: 1.0
-- Author: TDD Implementation for Task #78
-- Context: Phase 2 of Dynamic Prompt System (#77)
-- 
-- This migration creates a prompts table to store AI agent prompts
-- that can be managed via database instead of hardcoded files.
-- Supports versioning, soft-delete, and efficient lookups.

-- ============================================================================
-- TABLE: prompts
-- ============================================================================
-- Stores AI agent prompts with support for:
-- - Multiple agent types (question_filter, question_analyzer, reading_agent)
-- - Version control for prompt iterations
-- - Soft-delete capability via is_active flag
-- - Full-text prompt content (7000+ characters supported)
-- ============================================================================

CREATE TABLE prompts (
    -- Primary Key: UUID auto-generated
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Agent identifier: UNIQUE constraint ensures one active prompt per agent
    agent_name VARCHAR(50) UNIQUE NOT NULL,
    
    -- Prompt content: TEXT type supports unlimited length for large prompts
    prompt_content TEXT NOT NULL,
    
    -- Version tracking: Starts at 1, must be positive
    version INT NOT NULL DEFAULT 1 CHECK (version > 0),
    
    -- Soft-delete flag: true = active, false = deleted/inactive
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Audit timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Constraint: agent_name must be one of the allowed values
    CONSTRAINT chk_agent_name CHECK (
        agent_name IN ('question_filter', 'question_analyzer', 'reading_agent')
    )
);

-- ============================================================================
-- INDEX: Composite index for efficient agent lookups
-- ============================================================================
-- Optimizes queries that filter by agent_name AND is_active
-- Common query pattern: SELECT * FROM prompts WHERE agent_name = ? AND is_active = true
-- ============================================================================

CREATE INDEX idx_prompts_agent_active ON prompts(agent_name, is_active);

-- ============================================================================
-- TRIGGER: Auto-update updated_at timestamp
-- ============================================================================

CREATE OR REPLACE FUNCTION update_prompts_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_prompts_updated_at
    BEFORE UPDATE ON prompts
    FOR EACH ROW
    EXECUTE FUNCTION update_prompts_updated_at();

-- ============================================================================
-- COMMENTS: Table and column documentation
-- ============================================================================

COMMENT ON TABLE prompts IS 'Stores AI agent prompts for the tarot reading system with version control';
COMMENT ON COLUMN prompts.id IS 'UUID primary key, auto-generated';
COMMENT ON COLUMN prompts.agent_name IS 'Agent identifier: question_filter, question_analyzer, or reading_agent';
COMMENT ON COLUMN prompts.prompt_content IS 'Full prompt template with {placeholder} syntax for variable substitution';
COMMENT ON COLUMN prompts.version IS 'Version number for tracking prompt iterations (starts at 1)';
COMMENT ON COLUMN prompts.is_active IS 'Soft-delete flag: true = active, false = deleted';
COMMENT ON COLUMN prompts.created_at IS 'Timestamp when prompt was created';
COMMENT ON COLUMN prompts.updated_at IS 'Timestamp when prompt was last modified';

-- ============================================================================
-- SEED DATA: Initial prompts from /prompts/*.md files
-- ============================================================================
-- ON CONFLICT DO NOTHING ensures idempotent migration (safe to run multiple times)
-- ============================================================================

